WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_sl_solution_complex'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '复合对策题', 'kp-sl-solution-complex', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "提出对策：复合对策题"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心要求：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "不仅要提对策，还要先概括问题！"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "“指出材料中存在的问题，并提出对策”。（两问题）"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、实战心法"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "第一段先用精炼的语言把问题 1,2,3 罗列出来。"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "第二段提出对策 1,2,3。注意：【对策必须和问题一一对应】！问题提了 3 个，对策就必须是解决这 3 个问题的药方，绝不能脱节！"}]}]}$$ AS jsonb), NULL, '复合对策题的核心考点与高分作答技巧。', category_node.id, CAST('["申论", "提出对策", "复合对策"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_sl_solution_complex", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
